SELECT t.id AS ticketId, t.ticket_no AS ticketNo, e.title AS eventTitle, e.location AS eventLocation, e.start_time AS eventStartTime, e.end_time AS eventEndTime, e.status AS eventStatus, t.status, t.created_at AS createdAt, t.checked_at AS checkedAt, t.event_id AS eventId FROM ticket t LEFT JOIN event e ON t.event_id = e.id WHERE t.user_id = #{userId}
AND t.status = #{status}
ORDER BY t.created_at DESC

SELECT t.id AS ticketId, t.ticket_no AS ticketNo, u.username, t.status, t.created_at AS createdAt, t.checked_at AS checkedAt FROM ticket t LEFT JOIN user u ON t.user_id = u.id WHERE t.event_id = #{eventId}
AND t.status = #{status}
ORDER BY t.created_at DESC

